style.css:
css 
/* Pastel Study Bunny — MyEdSpace */

:root {
  /* swap these colors if you want */
  --my-pink: #f6c9dc;
  --my-lilac: #ded4f5;
  --my-cream: #fff9f5;
  --my-text: #68566c;
  --my-accent: #c58eae;
}

/* soft background and typography */
body {
  background-color: var(--my-cream) !important;
  color: var(--my-text) !important;
  font-family: "Trebuchet MS", sans-serif !important;
}

/* pretty links */
a {
  color: #b477a1 !important;
  text-decoration-color: var(--my-pink) !important;
}

/* softer buttons */
button,
input[type="button"],
input[type="submit"] {
  background: var(--my-pink) !important;
  color: #684b64 !important;
  border: 1px solid #edbcd3 !important;
  border-radius: 16px !important;
  box-shadow: 0 3px 9px #e9c9d655 !important;
}

/* rounded images */
img {
  border-radius: 14px !important;
}

/* softer form fields */
input,
textarea,
select {
  border: 1px solid #e8d5ed !important;
  border-radius: 12px !important;
  background-color: #fffafd !important;
  color: var(--my-text) !important;
}
